//! `xaea completions <SHELL>`: scripts are generated by clap_complete from
//! the real argument parser, so they must exist and be shell-plausible for
//! every supported shell, offer the `--decoder` value-enum candidates, and
//! clap must reject shells the enum doesn't know.

use std::process::Command;

fn completions(shell: &str) -> std::process::Output {
    Command::new(env!("CARGO_BIN_EXE_xaea"))
        .args(["completions", shell])
        .output()
        .expect("run xaea")
}

fn script(shell: &str) -> String {
    let out = completions(shell);
    assert!(
        out.status.success(),
        "{shell}: exit {}\nstderr: {}",
        out.status,
        String::from_utf8_lossy(&out.stderr)
    );
    String::from_utf8(out.stdout).expect("utf-8 script")
}

#[test]
fn each_shell_emits_a_plausible_script() {
    // (shell, a marker only that shell's generator produces)
    for (shell, marker) in [
        ("bash", "complete -F"),
        ("zsh", "#compdef xaea"),
        ("fish", "complete -c xaea"),
        ("elvish", "edit:completion"),
        ("powershell", "Register-ArgumentCompleter"),
    ] {
        let s = script(shell);
        assert!(s.len() > 500, "{shell}: script suspiciously short");
        assert!(s.contains("xaea"), "{shell}: script never names the binary");
        assert!(
            s.contains(marker),
            "{shell}: script lacks expected marker {marker:?}"
        );
    }
}

#[test]
fn decoder_enum_values_are_offered() {
    // The generator consumes the real Cli, so --decoder's value-enum
    // candidates must show up — bash/zsh/fish all spell them out.
    for shell in ["bash", "zsh", "fish"] {
        let s = script(shell);
        for value in ["lzma-turbo", "liblzma", "libcompression"] {
            assert!(
                s.contains(value),
                "{shell}: completions never offer --decoder {value}"
            );
        }
    }
}

#[test]
fn subcommands_and_aliases_are_completed() {
    let s = script("bash");
    for word in ["inspect", "extract", "completions"] {
        assert!(s.contains(word), "bash: subcommand {word} not completed");
    }
}

#[test]
fn bogus_shell_is_rejected_with_the_valid_list() {
    let out = completions("nonsense");
    assert!(!out.status.success(), "bogus shell accepted");
    let err = String::from_utf8_lossy(&out.stderr);
    assert!(err.contains("invalid value"), "unexpected error: {err}");
    for shell in ["bash", "zsh", "fish"] {
        assert!(
            err.contains(shell),
            "error doesn't list valid shell {shell}: {err}"
        );
    }
}
